#pragma once
int runPhoneRemoteSmoke(){
 juce::ScopedJuceInitialiser_GUI gui;auto root=LibraryStore::root();root.createDirectory();auto a=root.getChildFile("Remote A.mid"),b=root.getChildFile("Remote B.mid");SequenceClip clip;clip.notes={{1,60,100,1,0,1}};clip.save(a);clip.save(b);
 RackProcessor first,second;first.loops[0]->autoSave=false;second.loops[0]->autoSave=false;first.loops[0]->loadSequence(a);second.loops[0]->loadSequence(b);first.loops[0]->setMidiAdvanceBrowserOrder({a,b});second.loops[0]->setMidiAdvanceBrowserOrder({a,b});auto wa=root.getChildFile("Remote A.wav"),wb=root.getChildFile("Remote B.wav");for(auto file:{wa,wb}){juce::WavAudioFormat wav;auto stream=file.createOutputStream();std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(stream.release(),8000,1,16,{},0));juce::AudioBuffer<float> audio(1,8000);audio.clear();writer->writeFromAudioSampleBuffer(audio,0,8000);}first.loops[1]->autoSave=false;first.loops[1]->installAudio(first.loops[1]->readAudio(wa));first.loops[1]->setAdvanceBrowserOrder({wa,wb});PhoneRemote::instance().open(false);root.getChildFile("remote-url.txt").replaceWithText(PhoneRemote::instance().address());
 auto until=juce::Time::getMillisecondCounterHiRes()+12000;while(juce::Time::getMillisecondCounterHiRes()<until)CFRunLoopRunInMode(kCFRunLoopDefaultMode,.01,true);
 bool ok=LibraryStore::read("favourites.json").hasProperty(a.getFullPathName())&&first.loops[0]->sequence.path==a.getFullPathName()&&first.loops[1]->audio->path==wa.getFullPathName();std::cout<<(ok?"Phone remote smoke passed\n":"Phone remote smoke failed\n");return ok?0:1;
}
